DATE='27 November 2026'; LABEL='Ad-hoc opinion · Eyewear and medtech'; FOOT=f'Syz Research · Ad-hoc opinion · {DATE}'
SRC='Sources: Syz Research, Bloomberg, company data'
cover=dict(
 headline='EssilorLuxottica: strong results, a share price still far below its high',
 sub1=f'{DATE} · Syz Research',
 notice='Prices are as of the close on 27 November 2026. Company figures come from the third-quarter 2026 revenue release of 20 October 2026. Forward price-to-earnings multiples and averages are Syz calculations based on Bloomberg consensus data. This note is not a recommendation for any individual investor.',
 kpis=[('Q3 2026 revenue','EUR 7.49bn','+7.2% at constant exchange rates'),
       ('Wearables revenue, Q3','EUR 486m','+20% at constant exchange rates'),
       ('Myopia management, Q3','+24%','Same growth over nine months'),
       ('Share price','EUR 172.15','-36% since the start of 2026')],
 h2='Results that beat expectations, a valuation that has not followed',
 left=[('sub2','Growth in the core and in new categories'),
  ('p','EssilorLuxottica owns the whole chain, from lenses and frames to retail banners such as LensCrafters and Sunglass Hut. In the third quarter, revenue rose 9% to EUR 7.49bn, or 7.2% at constant exchange rates, ahead of analyst forecasts. Eyecare and Medtech grew 6.5%, comparable sales in the group\'s own stores rose 6.8% and Asia-Pacific led the regions with +15.7%.'),
  ('p','Two newer categories add to this base. Wearables, which groups AI glasses and hearing glasses, reached EUR 486m, up 20%. The myopia management portfolio, led by Stellest lenses for children, grew 24% in the quarter and over nine months. Stellest is now distributed in about 12,000 doors in the United States, following its FDA authorisation in September 2025.'),
  ('p','In June 2026 the group also signed a long-term joint development agreement with Applied Materials, focused on waveguides and adaptive lens systems for future smart glasses.')],
 right=[('sub2','A share price that has only partly recovered'),
  ('p','The shares jumped 15.5% on 21 October, from EUR 150.50 to EUR 173.80, and reached EUR 193.80 on 6 November. They have since given back part of the move and closed at EUR 172.15, 36% below the end of 2025 and 39% below the January high of EUR 282. The low of the year, EUR 139.00, came on 18 September.'),
  ('p','Wearables growth of 20% is a slowdown from the second quarter, when the category almost doubled, and investors are weighing how profitable smart glasses will be while volumes build.'),
  ('sub2','What this means for investors'),
  ('p','Expected earnings have barely moved: consensus for the next twelve months is EUR 7.80 per share, against EUR 7.87 a year ago. The fall in the share price has therefore come from a lower multiple. The shares trade on 22.1 times expected earnings, against averages of 27.1 times over five years and 27.5 times over ten. Wearables growth, the pace of the Stellest roll-out and the margin commentary at the next results are the data points to follow.')])
fiche=dict(
 title='EssilorLuxottica (EL FP)',
 subtitle='A vertically integrated eye-care group, on a multiple well below its five-year average',
 kpis=[('Share price','EUR 172.15','-36% year to date'),
       ('Forward P/E','22.1x','Five-year average: 27.1x'),
       ('Q3 revenue growth','+7.2%','At constant exchange rates'),
       ('Expected EPS, 12 months','EUR 7.80','EUR 7.87 a year ago')],
 tech=[('Technical trend','Basing'),('Support','EUR 150.5 / 139.0'),('Resistance','EUR 176.4 / 193.8'),('200-day average','EUR 176.4')],
 techline='The share price sits between its 40-day (EUR 170.9) and 200-day (EUR 176.4) averages, after giving back part of the rally that followed the results. A close above EUR 193.8, the high of 6 November, could confirm the recovery; EUR 150.5, the close before the results, is the level to watch on the downside.',
 left=[('h3','1. What the company does'),
  ('p','EssilorLuxottica designs, makes and sells prescription lenses (Essilor, Varilux, Transitions), frames and sunglasses (Ray-Ban, Oakley and licensed brands) and operates retail banners such as LensCrafters and Sunglass Hut. Its Eyecare and Medtech activities now also include myopia management, hearing glasses and ophthalmic equipment.'),
  ('h3','2. Why it could do well'),
  ('p','Third-quarter revenue grew 7.2% at constant exchange rates, with Asia-Pacific up 15.7%. Stellest, now in about 12,000 US doors, grew 24%, and the wearables business grew 20% to EUR 486m. A smart frame can also carry prescription and light-adaptive lenses, which could add lens value to each pair sold.'),
  ('h3','3. What sets it apart'),
  ('p','Owning lenses, frames, brands and stores lets the group sell premium products directly and collect the margin at each step. Its partnership with Meta has created a new category, and the agreement with Applied Materials aims to bring in-house expertise in waveguides and adaptive lenses for future glasses.')],
 right=[('h3','4. Is the share cheap?'),
  ('p','Cheaper than its own history. At EUR 172.15 the shares trade on 22.1 times consensus earnings for the next twelve months, against 27.1 times on average over five years and 27.5 times over ten. Over the past five years the multiple has been lower on only about 8% of trading days. Earnings estimates are almost unchanged (EUR 7.80, against EUR 7.94 at the start of the year), so the lower share price reflects a lower multiple. A low multiple can stay low if the market doubts the margins of new products.'),
  ('h3','5. Main risks'),
  ('p','Wearables could remain less profitable than the core business while volumes grow. The category depends on one partner, Meta, and could draw more competition and privacy scrutiny. Weaker consumer spending, notably in the United States, could slow store traffic and push buyers towards cheaper lenses. Currency moves also matter: reported growth of 9% compares with 7.2% at constant rates.'),
  ('h3','6. What to watch next'),
  ('p','Full-year results and any margin commentary; whether wearables growth stabilises after the slowdown from the second quarter; the pace of the Stellest roll-out in the United States; progress on the Applied Materials programme and on future smart glasses.')],
 concl='EssilorLuxottica reported solid third-quarter growth, with Asia-Pacific, myopia management and wearables ahead of the core. Earnings expectations have held up, while the share price is 36% lower than at the start of the year and the multiple is below its five and ten-year averages. The next phase depends on whether wearables can grow while keeping acceptable margins, and on the continued rise of Stellest. Concentration on one partner and the consumer backdrop are the main risks.')
charts=[('Chart 1','EL FP: share price over two years','Daily close with 40-day and 200-day simple moving averages, EUR, to 27 November 2026; the dashed line marks the Q3 revenue release','chart1_price.png'),
 ('Chart 2','EL FP: forward P/E over ten years','Price over consensus earnings for the next twelve months, with the ten-year average','chart2_pe.png'),
 ('Chart 3','EL FP: consensus earnings per share','EUR, expected earnings for the next twelve months; estimates have held broadly stable while the share price fell','chart3_eps.png')]
